def _local_name(tag):
    return tag.rsplit("}", 1)[-1]


def _panel_ids(svg_filepath):
    """Return geometry IDs below a PANEL group or Illustrator PANEL root."""

    root = ET.parse(svg_filepath).getroot()
    ids = []
    panel_containers = []
    if (
        _local_name(root.tag) == "svg"
        and root.get("id", "").upper() == "PANEL"
    ):
        # Illustrator's basic SVG export puts the PANEL identifier on its
        # root <svg>, rather than wrapping paths in <g id="PANEL">.
        panel_containers.append(root)
    panel_containers.extend(
        element
        for element in root.iter()
        if _local_name(element.tag) == "g"
        and element.get("id", "").upper() == "PANEL"
    )
    for container in panel_containers:
        for element in container.iter():
            if element is container:
                continue
            element_id = element.get("id")
            if element_id:
                ids.append(element_id)
    if not ids:
        raise RuntimeError("SVG 中没有找到 PANEL 组内带 id 的版片路径。")
    return set(ids)


def _object_source_names(obj):
    names = {obj.name}
    if obj.data is not None:
        names.add(obj.data.name)
    return {_PANEL_COPY_SUFFIX.sub("", name) for name in names}


def _import_panel_curves(svg_filepath, panel_ids=None):
    if bpy.context.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")

    if panel_ids is None:
        panel_ids = _panel_ids(svg_filepath)
    before = set(bpy.data.objects)
    result = bpy.ops.import_curve.svg(filepath=str(svg_filepath))
    if result != {"FINISHED"}:
        raise RuntimeError("Blender SVG 导入失败。")

    imported = [obj for obj in bpy.data.objects if obj not in before]
    panel_curves = [
        obj
        for obj in imported
        if obj.type == "CURVE" and (_object_source_names(obj) & panel_ids)
    ]
    if not panel_curves:
        imported_names = ", ".join(sorted(obj.name for obj in imported)) or "无"
        raise RuntimeError(
            "SVG 已导入，但没有找到与 PANEL 路径 id 对应的 Curve。"
            f"导入对象：{imported_names}"
        )

    # SEAM and HEM geometry is read directly from the SVG later.  Removing its
    # imported guide objects keeps the scene clean and prevents accidental joins.
    for obj in imported:
        if obj not in panel_curves:
            bpy.data.objects.remove(obj, do_unlink=True)

    bpy.ops.object.select_all(action="DESELECT")
    for curve in panel_curves:
        curve.select_set(True)
    bpy.context.view_layer.objects.active = panel_curves[0]

    if len(panel_curves) > 1:
        result = bpy.ops.object.join()
        if result != {"FINISHED"}:
            raise RuntimeError("PANEL Curve 合并失败。")

    panel = bpy.context.active_object
    panel.name = f"{Path(svg_filepath).stem}_PANELS"
    return panel


def _load_script(script_name, module_name):
    """Execute a Blender script without triggering its __main__ block."""

    namespace = {
        "__file__": f"<embedded:{script_name}>",
        "__name__": module_name,
        "__package__": None,
    }
    try:
        payload = _EMBEDDED_SCRIPTS[script_name]
    except KeyError as error:
        raise RuntimeError(f"缺少内嵌脚本：{script_name}") from error
    source = zlib.decompress(base64.b85decode(payload)).decode("utf-8-sig")
    exec(compile(source, namespace["__file__"], "exec"), namespace)
    return namespace


def _group_vertex_indices(obj, group_name):
    group = obj.vertex_groups.get(group_name)
    if group is None:
        return set()
    return {
        vertex.index
        for vertex in obj.data.vertices
        if any(
            membership.group == group.index and membership.weight > 0.001
            for membership in vertex.groups
        )
    }


def _is_seam_group(name):
    """Seam paths (S001_LEFT, SEAM_*), excluding their single-vertex A/B ends."""

    if name.endswith(("_A", "_B")):
        return False
    if name.startswith("SEAM_"):
        return True
    seam_id = name.split("_", 1)[0]
    return seam_id.startswith("S") and seam_id[1:].isdigit()


def _is_hem_group(name):
    return name == "HEM" or name.startswith("HEM_")


def _panel_edge_vertices(obj, panel_vertices, predicate):
    """Vertices of the matching groups that lie on this panel, by group name."""

    found = {}
    for group in obj.vertex_groups:
        if predicate(group.name):
            vertices = _group_vertex_indices(obj, group.name) & panel_vertices
            if vertices:
                found[group.name] = vertices
    return found


def _stand_panel_seam_up(obj, panel_name):
    """Rotate one flat side panel 90 degrees so its seam is on top, hem below.

    The seam and hem are recognized from the vertex groups created by
    generate_sewing.py, restricted to this panel's vertices, so the result does
    not depend on how the panel was laid out or mirrored in the SVG. The panel
    rotates about its center around the layout axis (X or Y) perpendicular to
    the seam-to-hem direction, which takes that direction straight down (-Z).
    """
    panel_vertices = _group_vertex_indices(obj, panel_name)
    if not panel_vertices:
        raise RuntimeError(f"Cloth Mesh 缺少顶点组或顶点组为空：{panel_name}")
    seams = _panel_edge_vertices(obj, panel_vertices, _is_seam_group)
    if not seams:
        raise RuntimeError(
            f"{panel_name} 上没有识别到缝线顶点组（Sxxx_* / SEAM_*）；"
            "请检查 SVG 的 SEAM 组。"
        )
    hems = _panel_edge_vertices(obj, panel_vertices, _is_hem_group)

    coordinates = obj.data.vertices
    def centroid(indices):
        total = Vector((0.0, 0.0, 0.0))
        for index in indices:
            total += coordinates[index].co
        return total / len(indices)

    seam_vertices = set().union(*seams.values())
    seam_center = centroid(seam_vertices)
    # Without a HEM group the hem is the panel side opposite the seam.
    hem_center = centroid(set().union(*hems.values()) if hems else panel_vertices)
    offset = hem_center - seam_center
    if max(abs(offset.x), abs(offset.y)) < 1.0e-6:
        raise RuntimeError(f"{panel_name} 的缝线与下摆位置重合，无法判断朝向。")
    # Snap to the dominant layout axis: an oblique axis from curved seams
    # would tilt the long panel along its length.
    if abs(offset.y) >= abs(offset.x):
        direction = Vector((0.0, 1.0 if offset.y > 0.0 else -1.0, 0.0))
    else:
        direction = Vector((1.0 if offset.x > 0.0 else -1.0, 0.0, 0.0))
    axis = direction.cross(Vector((0.0, 0.0, -1.0))).normalized()
    pivot = centroid(panel_vertices)
    rotation = Matrix.Rotation(radians(90.0), 3, axis)
    for index in panel_vertices:
        vertex = coordinates[index]
        vertex.co = pivot + rotation @ (vertex.co - pivot)
    obj.data.update()

    seam_z = centroid(seam_vertices).z
    hem_z = centroid(set().union(*hems.values())).z if hems else pivot.z
    if seam_z <= hem_z:
        raise RuntimeError(f"{panel_name} 旋转后缝线未在下摆上方。")
    return {
        "seams": ", ".join(sorted(seams)),
        "hems": ", ".join(sorted(hems)) or "（无 HEM，按缝线对侧）",
        "axis": tuple(round(value, 3) for value in axis),
        "seam_above_hem_mm": (seam_z - hem_z) * 1000.0,
    }


def _move_vertex_group_z(obj, group_name, distance):
    """Move one panel vertex group along the object's Z axis."""
    group = obj.vertex_groups.get(group_name)
    if group is None:
        raise RuntimeError(f"Cloth Mesh 缺少顶点组：{group_name}")

    group_index = group.index
    vertices = [
        vertex
        for vertex in obj.data.vertices
        if any(membership.group == group_index for membership in vertex.groups)
    ]
    if not vertices:
        raise RuntimeError(f"顶点组没有顶点：{group_name}")

    for vertex in vertices:
        vertex.co.z += distance

    obj.data.update()


def _ensure_front_faces_up(obj):
    """Orient flat panel faces toward +Z before folding the side panels."""
    mesh = obj.data
    mesh.update()
    for polygon in mesh.polygons:
        if polygon.normal.z < 0:
            polygon.flip()
    mesh.update()


def run_workflow(svg_filepath, roof_pin=False):
    svg_filepath = Path(svg_filepath).resolve()
    if svg_filepath.suffix.lower() != ".svg" or not svg_filepath.is_file():
        raise RuntimeError(f"请选择有效的 SVG 文件：{svg_filepath}")

    sewing = _load_script("generate_sewing.py", "_cc_workflow_generate_sewing")
    semantic_data = sewing["_semantic_svg"](str(svg_filepath))
    print(f"[CC WORKFLOW] 1/6 导入 SVG：{svg_filepath}")
    panel = _import_panel_curves(svg_filepath, set(semantic_data[0]))
    print(f"[CC WORKFLOW] 2/6 PANEL Curve 已合并：{panel.name}")

    # remesh.py currently performs its work at module scope.  It leaves the new
    # cloth mesh active and selected, which is exactly the contract needed here.
    _load_script("remesh.py", "_cc_workflow_remesh")
    cloth = bpy.context.active_object
    if cloth is None or cloth.type != "MESH" or not cloth.get("cloth_panel_count"):
        raise RuntimeError("remesh.py 未生成有效的活动 Cloth Mesh。")
    print(f"[CC WORKFLOW] 3/6 Cloth Mesh 已生成：{cloth.name}")

    loose_edges = sewing["build_semantic_sewing"](
        cloth, str(svg_filepath), semantic_data=semantic_data
    )
    print(f"[CC WORKFLOW] 4/6 Sewing 已生成：{loose_edges} 条 Loose Edge")

    _ensure_front_faces_up(cloth)
    for panel_name in ("PANEL_LEFT", "PANEL_RIGHT"):
        result = _stand_panel_seam_up(cloth, panel_name)
        _move_vertex_group_z(cloth, panel_name, -1.0)
        print(
            f"[CC WORKFLOW]     {panel_name}: 缝线 {result['seams']} 在上，"
            f"下摆 {result['hems']} 在下（高差 {result['seam_above_hem_mm']:.0f} mm，"
            f"旋转轴 {result['axis']}）"
        )
    print("[CC WORKFLOW] 5/6 PANEL_LEFT/PANEL_RIGHT 已按缝线在上、下摆在下立起并向下移动 1 m")

    bpy.ops.object.select_all(action="DESELECT")
    cloth.select_set(True)
    bpy.context.view_layer.objects.active = cloth
    cloth_setup = _load_script(
        "setup_cloth.py", "_cc_workflow_setup_cloth"
    )
    # The embedded cloth.py reads this module-level switch at call time.
    cloth_setup["ENABLE_ROOF_PIN_DURING_SIMULATION"] = bool(roof_pin)
    cloth_setup["main"]()
    print(f"[CC WORKFLOW] 6/6 Cloth 设置完成：{cloth.name}")
    return cloth


class CC_OT_svg_cloth_workflow(bpy.types.Operator, ImportHelper):
    """选择语义 SVG 并完成导入、网格、缝合及 Cloth 设置"""

    bl_idname = "cc.svg_cloth_workflow"
    bl_label = "SVG → Cloth 完整工作流"
    bl_options = {"REGISTER", "UNDO"}
    filename_ext = ".svg"
    filter_glob: bpy.props.StringProperty(default="*.svg", options={"HIDDEN"})
    roof_pin: bpy.props.BoolProperty(
        name="固定车顶顶点",
        description="缝合初期临时固定 PANEL_TOP 中心顶点 (PIN_ROOF)；关闭则车顶顶点完全自由",
        default=False,
    )

    def execute(self, context):
        try:
            cloth = run_workflow(self.filepath, roof_pin=self.roof_pin)
        except (ET.ParseError, OSError, RuntimeError, ValueError) as error:
            self.report({"ERROR"}, str(error))
            print(f"[CC WORKFLOW ERROR] {error}")
            return {"CANCELLED"}
        pin = "开启" if self.roof_pin else "关闭"
        self.report({"INFO"}, f"完整工作流完成：{cloth.name}（车顶顶点固定：{pin}）")
        return {"FINISHED"}


def launch_svg_dialog():
    previous = getattr(bpy.types, CC_OT_svg_cloth_workflow.__name__, None)
    if previous is not None:
        try:
            bpy.utils.unregister_class(previous)
        except RuntimeError:
            pass
    bpy.utils.register_class(CC_OT_svg_cloth_workflow)
    if bpy.app.background:
        raise RuntimeError("后台模式请直接调用 run_workflow(svg_filepath)。")
    return bpy.ops.cc.svg_cloth_workflow("INVOKE_DEFAULT")


if __name__ == "__main__":
    launch_svg_dialog()
